"""Build current construction-state plan/shotlist from selected photographic references; no media jobs."""
from pathlib import Path
import json,hashlib,html
R=Path(__file__).resolve().parents[1];P=R/'outputs/production';E=html.escape
budget=json.loads((P/'budget.json').read_text())
refs={'MASTER':'outputs/keyframes/kitchen-smeg-enclosure-v2.png','WEST':'outputs/keyframes/west-phone-speaker-realism-v1.png','FINAL':'outputs/keyframes/apartment-fridge-reconstruction-v11.png','WORKERS':'outputs/keyframes/workers-v1.png','BEFORE-A':'references/original/ref-a-cooking-run.webp','BEFORE-B':'references/original/ref-b-sink-run.webp','BEFORE-H':'references/original/ref-h-apartment-facing.webp'}
# Stable editorial IDs. Multiple atomic takes may occupy one editorial shot.
rows=[
('01',0,5,'Original kitchen → prepared room','BEFORE-A','Old kitchen; original fridge remains','Remove old OTR/range; room prepared; old fridge retained',[('A',1,'Establish the original kitchen'),('B',1.4,'Two workers remove the old over-range microwave'),('C',1.4,'Workers roll out the old electric range'),('D',1.2,'Remove the wooden floor lamp in the supported apartment angle')]),
('02',5,10,'Floor and base cabinets','MASTER','Prepared room; old fridge retained','Concrete and new base cabinets; no quartz yet',[('A',2.5,'Trowel one clear section of the concrete floor'),('B',2.5,'Level and fasten one base cabinet; cut to cumulative installed bases')]),
('03',10,15,'Seat cooking-run quartz','MASTER','Bases ready; exposed cooking-run cabinet tops; old fridge','Quartz fully seated on cooking run; no sink cutout here',[('A',5,'Two workers lower the already-aligned quartz through its final short descent and release only after full seating')]),
('04',15,20,'Sink-side equipment','WEST','West base run ready','Single sink, L faucet/dispenser and base microwave left of sink installed; DW retained',[('A',2,'Seat the single sink in the prepared west counter'),('B',1.5,'Secure the L faucet at its existing location'),('C',1.5,'Slide the microwave into its base-cabinet opening left of sink')]),
('05',20,25,'Backsplash and uppers','MASTER','Counters and sink equipment installed','Stone backsplash and Shaker/frosted uppers installed',[('A',2.5,'Seat one backsplash slab against the cooking wall'),('B',2.5,'Fasten an upper cabinet to prepared mounting points')]),
('06',25,31,'Cooking equipment','MASTER','Backsplash/uppers installed','Pale hood, pot filler and red-knob gas range installed',[('A',2,'Secure the pale hood assembly'),('B',1.5,'Fasten the pot filler'),('C',2.5,'Guide the gas range through its final positioning movement')]),
('07',31,35,'French-door refrigerator','FINAL','Old fridge still present; new opening prepared between cuts','Selected third-view French-door fridge and enclosure in place',[('A',1.5,'Roll the old refrigerator out'),('B',2.5,'After an editorial preparation cut, guide the new French-door refrigerator into its enclosure')]),
('08',35,39,'Commission lighting','MASTER','Installed equipment; lighting not yet commissioned','Interior/undercabinet/hood lights ON and remain on',[('A',4,'Operate switches and visibly bring the installed warm lighting on')]),
('09',39,44,'North station and west charging nook','MASTER','Major kitchen complete, north service station unfinished','Coffee/wine station installed; west nook holds phone and speaker',[('A',1.5,'Finish a small visible wall section'),('B',1.5,'Seat the wine unit in the prepared opening'),('C',1.2,'Place the dial espresso machine on its north-wall niche surface'),('D',.8,'Dock the phone beside the speaker in the small west nook')]),
('10',44,49,'Oak bar front','FINAL','Kitchen complete; bar-front backing exposed','Ribbed-oak bar front secured',[('A',5,'Two workers align and secure one ribbed-oak panel; cut to the completed bar')]),
('11',49,55,'Furnish and finish','FINAL','Finished kitchen; two stools staged, third being placed','Three stools and selected styling present; active work ends at55',[('A',2.4,'Lower the third stool facing the bar, matching the two parked stools'),('B',.8,'Set the red toaster left of range'),('C',.8,'Set the red kettle right of range'),('D',1,'Position the dining rug edge beneath the table'),('E',1,'Place the selected final vase; other final styling established across the editorial cut')]),
('12',55,57,'Kitchen reveal','MASTER','All final features in place','Finished kitchen remains unchanged',[('A',2,'Hold the widest source-supported kitchen reveal with no new geometry')]),
('13',57,60,'Apartment-facing final','FINAL','All final features in place','Final selected photograph appearance held through60',[('A',3,'Restrained final apartment-facing reveal matching the restored photograph')])]
style='Photoreal construction film. Fixed source-based room/camera; two consistent workers. Lead: short grey hair, navy shirt, dark trousers, tan tool belt. Partner: grey shirt, dark trousers, dark cap, dark tool belt. Rigid objects, believable weight/contact. No morphing, teleporting, duplicates, narration, music, captions or overlays. Construction sound only. One atomic action per take; time jumps happen in edit.'
shots=[]
for sid,start,end,title,view,before,after,actions in rows:
 cursor=start;takes=[]
 for letter,dur,action in actions:
  tid=sid+letter;take_view={'01D':'BEFORE-H','09D':'WEST','11B':'MASTER','11C':'MASTER'}.get(tid,view);paths=[refs[take_view],refs['WORKERS']]
  if take_view not in ['BEFORE-A','BEFORE-B','BEFORE-H']:paths.append(refs['BEFORE-B' if take_view=='WEST' else ('BEFORE-H' if take_view=='FINAL' else 'BEFORE-A')])
  geometry=refs[take_view] if take_view.startswith('BEFORE') else paths[-1]
  prompt=f'{style}\nShot {sid}, take {tid}. Current view reference: {refs[take_view]}. Workers: {refs["WORKERS"]}. Original geometry reference: {geometry}.\nSTART: {before}.\nACTION: {action}.\nEND: {after}.\nKeep only this action in the uninterrupted take. Preserve all already installed elements; new fridge arrives only in07, lighting stays ON after08. Microwave below counter LEFT of west sink; charging nook phone+speaker only; coffee/wine on north wall. Restored FINAL reference governs refrigerator/enclosure where visible, without reopening its design.\nMandatory stage START/END images are not yet generated. Attach and inspect both before submission; do not animate a finished photograph as an earlier construction state.'
  takes.append({'id':tid,'action':action,'edit_in':round(cursor,3),'edit_out':round(cursor+dur,3),'planned_source_duration_s':5,'duration_note':'Planning placeholder; verify current provider mode/quote before execution','source_in':None,'source_out':None,'status':'planned','references':paths,'view':take_view,'start_frame_planned':f'outputs/construction/{tid}-start.png','end_frame_planned':f'outputs/construction/{tid}-end.png','prompt':prompt});cursor+=dur
 assert abs(cursor-end)<1e-8
 shots.append({'id':sid,'title':title,'edit_in':start,'edit_out':end,'view':view,'start_state':before,'end_state':after,'takes':takes})
plan={'revision':'2026-10-10-photographic-restoration','status':'planning; B06a closed 2026-10-10; B07 stage frames pending authorization; no generation authorized','selected_references':{k:{'path':v,'sha256':hashlib.sha256((R/v).read_bytes()).hexdigest()} for k,v in refs.items()},'editorial_duration_s':60,'delivery_frames':1440,'delivery_fps':24,'selected_third_view':refs['FINAL'],'reference_limits':['User restored v11 visually; not construction-fit certification','MASTER is the B06a-corrected view 1 (kitchen-smeg-enclosure-v2); its fridge enclosure matches restored FINAL','Local3D studies are archived experiments, not production references'],'workers_review':'Lead re-inspected workers-v1 on2026-10-10; wardrobe/identities match prior contract; no new worker generation','first_motion_test':'03A quartz seating, after newly reviewed matching start/end stage frames','old_pilots':'Historical diagnostics only; no accepted production take','shots':shots}
(P/'construction-state-plan.json').write_text(json.dumps(plan,indent=2)+'\n')
catalog=json.loads((R/'docs/asset-catalog.json').read_text());assets={a['path']:a for a in catalog['assets']}
figures=[]
for label,path in refs.items():
 a=assets.get(path,{})
 figures.append(f'<figure><img loading="lazy" src="../{E(path)}" alt="{E(label)} reference"><figcaption><strong>{E(label)}</strong><br>{E(path)}<br><small>{E(a.get("id",""))} · Job: {E(a.get("job_id") or "source / not a generation receipt")}<br>{E(str(R/path))}</small></figcaption></figure>')
trs=[];cards=[]
for sh in shots:
 trs.append(f'<tr><th scope="row">{sh["id"]}</th><td>{sh["edit_in"]}–{sh["edit_out"]}s</td><td>{E(sh["start_state"])}</td><td>{E(sh["end_state"])}</td></tr>')
 body=[]
 for take in sh['takes']:
  tid=take['id'];body.append(f'<details><summary>{tid}: {E(take["action"])}</summary><p>Edit {take["edit_in"]}–{take["edit_out"]}s. Source generation: proposed5s, not quoted. Source trims: not selected.</p><p>Planned frames (do not exist): <code>{take["start_frame_planned"]}</code> → <code>{take["end_frame_planned"]}</code></p><label for="p-{tid}">Complete editable prompt {tid}</label><textarea id="p-{tid}" data-persist="{tid}-prompt">{E(take["prompt"])}</textarea><button type="button" data-copy="p-{tid}">Copy prompt</button></details>')
 cards.append(f'<article><h3>{sh["id"]} · {E(sh["title"])}</h3><p>{sh["edit_in"]}–{sh["edit_out"]}s · {E(sh["view"])}</p>{"".join(body)}<label for="s-{sh["id"]}">Review status</label><select id="s-{sh["id"]}" data-persist="{sh["id"]}-status"><option>planned</option><option>generated — uninspected</option><option>inspected — unresolved</option><option>accepted — evidence recorded</option></select><label for="n-{sh["id"]}">Inspection evidence / actual source trims</label><textarea id="n-{sh["id"]}" data-persist="{sh["id"]}-notes" rows="3"></textarea></article>')
old=(R/'outputs/shotlist.html').read_text();css=old.split('<style>',1)[1].split('</style>',1)[0]
css+='textarea{width:100%;min-height:8em;max-height:30em;resize:vertical}@supports(field-sizing:content){textarea{field-sizing:content;height:auto}}'
js='''const prefix="vero-kitchen-film:2026-10-10-restored:";const message=document.getElementById('message');for(const e of document.querySelectorAll('[data-persist]')){try{const v=localStorage.getItem(prefix+e.dataset.persist);if(v!==null)e.value=v}catch{}e.addEventListener('input',()=>{try{localStorage.setItem(prefix+e.dataset.persist,e.value)}catch{message.textContent='Browser storage unavailable; keep a copy of your edits.'}})}for(const b of document.querySelectorAll('[data-copy]'))b.addEventListener('click',async()=>{const t=document.getElementById(b.dataset.copy);try{await navigator.clipboard.writeText(t.value);message.textContent='Prompt copied.'}catch{t.focus();t.select();message.textContent='Prompt selected; press Command+C.'}});'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vero · construction plan</title><style>{css}</style></head><body><a class="skip" href="#content">Skip to plan</a><header><p class="eyebrow">Photographic workflow restored · 10 October2026</p><h1>A kitchen, built in sixty seconds.</h1><p>The user-restored third view is the selected final apartment view. Local3D studies are archived; no further design iteration.</p><div class="banner"><strong>Construction planning is current; paid execution is not authorized.</strong><p>Task {budget["task_quote_total"]}/{budget["ceiling_credits"]} credits. Opus assistance requested for B06a finished-view continuity. No construction frames or final motion takes generated. After B06a acceptance: matching start/end frames for quartz-seating test03A. No reuse of failed pilots.</p></div><nav><a href="../OPUS-HANDOFF.md">Opus handoff</a><a href="#refs">Selected references</a><a href="#continuity">State ledger</a><a href="#shots">Editable takes</a><a href="../docs/BACKLOG.md">Backlog</a></nav><p id="message" role="status"></p></header><main id="content"><section id="refs"><h2>Selected references</h2><p>Originals control topology; selected images control appearance. FINAL governs fridge/enclosure where visible. No recess/clearance or actual construction feasibility is proved by these images.</p><div class="refs">{''.join(figures)}</div></section><section id="continuity"><h2>Cumulative construction states</h2><div class="scroll"><table><caption>13 editorial shots ·60.000 seconds ·1440 frames at24fps</caption><thead><tr><th>Shot</th><th>Edit</th><th>Start</th><th>End / carried forward</th></tr></thead><tbody>{''.join(trs)}</tbody></table></div></section><section id="shots"><h2>Atomic takes</h2><p>Every take remains planned. Source duration5s is provisional and separate from edit duration; actual source trims remain unset. Prompt edits/statuses save locally when browser storage is available. Acceptance requires file/time evidence.</p>{''.join(cards)}</section><section><h2>Manifest and review boundary</h2><p><a href="production/construction-state-plan.json">Complete state/take manifest</a> · <a href="inspection.txt">Recorded inspection history</a> · <a href="stills-gallery.html">Asset catalog</a></p><p>Lead inspected existing worker sheet; construction-stage frames still required. Quartz pilot failed endpoint, stool pilot failed orientation, fridge pilot uses superseded appearance. No final shot accepted. Export target:1920×1080 H.264/AAC, construction sound only.</p></section></main><footer>Revision2026-10-10 photographic restoration. No public publishing or automatic generation.</footer><script>{js}</script></body></html>'''
(R/'outputs/shotlist.html').write_text(page)
print(json.dumps({'shots':len(shots),'atomic_takes':sum(len(x['takes']) for x in shots),'duration':60,'first_test':'03A','paid_spend':0}))
